use std::sync::Once;

static INIT: Once = Once::new();
static mut FILTER: Option<env_filter::Filter> = None;

struct SimpleLogger;

impl log::Log for SimpleLogger {
    fn enabled(&self, metadata: &Metadata) -> bool {
        unsafe {
            if let Some(filter) = &FILTER {
                filter.enabled(metadata)
            } else {
                true
            }
        }
    }

    fn log(&self, record: &Record) {
        if self.enabled(record.metadata()) {
            let now = Utc::now();
            let ts = now.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string();
            let level = match record.level() {
                Level::Error => "ERROR",
                Level::Warn => "WARN",
                Level::Info => "INFO",
                Level::Debug => "DEBUG",
                Level::Trace => "TRACE",
            };
            eprintln!("{} {:5} [{}] {}", ts, level, record.target(), record.args());
        }
    }

    fn flush(&self) {}
}

static LOGGER: SimpleLogger = SimpleLogger;

pub fn init(default_level: &str) {
    INIT.call_once(|| {
        let filter_str = std::env::var("RUST_LOG").unwrap_or_else(|_| default_level.to_string());
        let filter = env_filter::Builder::new().parse(&filter_str).build();
        unsafe {
            FILTER = Some(filter);
        }
        let _ = log::set_logger(&LOGGER);
        log::set_max_level(log::LevelFilter::Trace);
    });
}

