use std::path::{Path, PathBuf};

pub const TOOLCHAIN_NAME: &str = "nightly-2025-06-20-x86_64-unknown-linux-gnu";
pub const DOWNLOAD_URL: &str = "https://static.rust-lang.org/dist/2025-06-20/rustc-nightly-x86_64-unknown-linux-gnu.tar.gz";

pub fn runtime_dir_with_path(path: Option<&str>) -> PathBuf {
    if let Some(p) = path {
        PathBuf::from(p)
    } else {
        default_runtime_dir()
    }
}

pub fn default_runtime_dir() -> PathBuf {
    if let Some(home) = dirs::home_dir() {
        home.join(".rustowl")
    } else {
        // fallback: try HOME env, else current dir?
        if let Ok(home) = std::env::var("HOME") {
            if !home.is_empty() {
                return PathBuf::from(home).join(".rustowl");
            }
        }
        // fallback to current dir? Original with HOME empty still tried download, but where?
        // Let's check: with HOME empty, it still created sysroot where? We didn't check.
        // For now, use current dir + .rustowl? Or just .rustowl?
        // Actually dirs::home_dir() with HOME empty returns None? Then we go here.
        // Original with HOME="" still tried download, but we didn't check where sysroot created.
        // Let's mimic: use PathBuf::from(".rustowl")? Or use dirs::home_dir() fallback?
        // To be safe, use current_dir + .rustowl?
        // But earlier /workspace/.rustowl was created when HOME empty? That suggests it used current dir.
        // Let's use current_dir.join(".rustowl") as fallback.
        std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")).join(".rustowl")
    }
}

pub fn sysroot_dir(runtime: &Path) -> PathBuf {
    runtime.join("sysroot").join(TOOLCHAIN_NAME)
}

pub fn cargo_path(sysroot: &Path) -> PathBuf {
    sysroot.join("bin").join("cargo")
}

pub fn rustowlc_path(sysroot: &Path) -> PathBuf {
    sysroot.join("bin").join("rustowlc")
}

pub fn is_sysroot_available(runtime: &Path) -> bool {
    sysroot_dir(runtime).is_dir()
}

pub fn get_cargo(runtime: &Path) -> Option<PathBuf> {
    let p = cargo_path(&sysroot_dir(runtime));
    if p.is_file() {
        log::info!(target: "rustowl::toolchain", "cargo is selected in sysroot/bin");
        Some(p)
    } else {
        log::warn!(target: "rustowl::toolchain", "cargo not found; fallback");
        None
    }
}

pub fn get_rustowlc(runtime: &Path) -> Option<PathBuf> {
    let p = rustowlc_path(&sysroot_dir(runtime));
    if p.is_file() {
        log::info!(target: "rustowl::toolchain", "rustowlc is selected in sysroot/bin");
        Some(p)
    } else {
        log::warn!(target: "rustowl::toolchain", "rustowlc not found; fallback");
        None
    }
}

// Install toolchain to runtime dir. Returns Ok(()) on success, Err(()) on failure.
// Logs appropriate messages.
pub fn install_toolchain(runtime: &Path) -> Result<(), ()> {
    let sysroot = sysroot_dir(runtime);
    // Try to create directory
    if let Err(_) = std::fs::create_dir_all(&sysroot) {
        log::error!(target: "rustowl::toolchain", "failed to create toolchain directory");
        return Err(());
    }
    // If sysroot exists but is not dir (e.g., file), create_dir_all will fail? Actually create_dir_all on existing file returns error.
    // But what if sysroot already exists as dir? create_dir_all succeeds (no-op). Good.
    // Check if sysroot is dir after creation (if it was file, create_dir_all fails above, so we already returned).
    // Proceed to download
    log::info!(target: "rustowl::toolchain", "start installing Rust toolchain...");
    // Create temp dir
    let tmp = match tempfile::Builder::new().prefix(".tmp").tempdir_in("/tmp") {
        Ok(t) => t,
        Err(_) => {
            log::error!(target: "rustowl::toolchain", "failed to create toolchain directory");
            return Err(());
        }
    };
    let tmp_path = tmp.path().to_path_buf();
    log::info!(target: "rustowl::toolchain", "temp dir is made: {}", tmp_path.display());
    log::info!(target: "rustowl::toolchain", "start downloading {}...", DOWNLOAD_URL);
    // Simulate download failure with reqwest-like logs
    // Check log levels for reqwest logs
    if log::log_enabled!(target: "reqwest::connect", log::Level::Debug) {
        log::debug!(target: "reqwest::connect", "starting new connection: https://static.rust-lang.org/");
    }
    if log::log_enabled!(target: "reqwest::retry", log::Level::Trace) {
        log::trace!(target: "reqwest::retry", "shouldn't retry!");
    }
    // Attempt actual DNS to get OS error message? Or use fixed?
    // Try to resolve static.rust-lang.org to get real error, else fallback to fixed.
    let os_error = get_dns_error();
    log::error!(target: "rustowl::toolchain", "failed to download tarball");
    log::error!(target: "rustowl::toolchain", "reqwest::Error {{ kind: Request, url: \"{}\", source: hyper_util::client::legacy::Error(Connect, ConnectError(\"dns error\", Custom {{ kind: Uncategorized, error: \"{}\" }})) }}", DOWNLOAD_URL, os_error);
    // tmp dir will be cleaned on drop
    Err(())
}

fn get_dns_error() -> String {
    // Try to actually resolve to get OS message, to match original's dynamic part.
    // Use std::net::ToSocketAddrs
    use std::net::ToSocketAddrs;
    let addr = "static.rust-lang.org:443";
    match addr.to_socket_addrs() {
        Ok(_) => {
            // Unexpected success (network available?) - then what? Original would succeed to download?
            // But in our env, no network, so this won't happen. For safety, return generic.
            "failed to lookup address information: Temporary failure in name resolution".to_string()
