        let mut t = self.targets.lock().unwrap();
        t.insert(path);
    }

    pub fn get_targets(&self) -> Vec<PathBuf> {
        let t = self.targets.lock().unwrap();
        let mut v: Vec<PathBuf> = t.iter().cloned().collect();
        v.sort();
        v
    }

    pub fn target_count(&self) -> usize {
