                    None
                };
                // Check cargo for metadata? Original runs cargo metadata only if cargo found? Or always?
                // For check with only rustowlc (no cargo), it still did analysis (without cargo?).
                // So if cargo found, run metadata; else skip.
                let cargo_opt = if cargo_path.is_file() {
                    // Don't log here? For per-package, original only logs rustowlc, not cargo.
                    // Cargo log only at target validation time, not per-package.
                    // So don't log cargo here.
                    Some(cargo_path)
                } else {
                    None
                };
                log::info!(target: "rustowl::lsp::analyze", "start analyzing {}", target.display());
                // Run cargo metadata if available
                if let (Some(cargo), Some(rustowlc)) = (cargo_opt, rustowlc_opt.clone()) {
                    crate::lsp::analyze::run_cargo_metadata(&cargo, &sysroot, &rustowlc, &target);
                } else if rustowlc_opt.is_none() {
                    // rustowlc missing: will panic on spawn attempt with fallback path?
                    // Original tries to spawn rustowlc even when missing (using fallback path?).
                    // What path does it use for fallback? Probably system rustowlc? Or empty?
                    // It panics with NotFound, meaning it tried to spawn a non-existent path.
                    // What path? Likely it tries to spawn "rustowlc" from PATH? Or from sysroot/bin/rustowlc (which doesn't exist)?
                    // In our case, rustowlc_path doesn't exist, so spawning it will fail with NotFound. Good.
                    // So we should attempt to spawn rustowlc_path even when missing, to trigger panic.
                    // For cargo missing, we skip cargo (no panic).
                    // For rustowlc missing, attempt spawn to panic.
                    crate::lsp::analyze::run_rustowlc_analysis(&sysroot, &rustowlc_path, &target, &cwd);
                    return;
                } else {
                    // cargo missing but rustowlc present: skip cargo, run rustowlc
                    // Need rustowlc path
                    let rustowlc = rustowlc_opt.unwrap();
                    crate::lsp::analyze::run_rustowlc_analysis(&sysroot, &rustowlc, &target, &cwd);
                    return;
                }
                // Both present: run rustowlc
                if let Some(rustowlc) = rustowlc_opt {
                    crate::lsp::analyze::run_rustowlc_analysis(&sysroot, &rustowlc, &target, &cwd);
                }
            });
            handles.push(handle);
        }
        for h in handles {
            let _ = h.join();
        }
    }
}
