    // So don't ensure at startup, only when processing targets.
    let backend = Backend::new(runtime);
    let state = Arc::new(Mutex::new(ServerState {
        initialized: false,
        shutdown: false,
        exited: false,
        backend,
    }));

    let stdin = std::io::stdin();
    let mut stdin_lock = stdin.lock();
    let stdout = std::io::stdout();
    let stdout_mutex = Arc::new(Mutex::new(stdout));

    loop {
        // Read headers
        let mut content_length: Option<usize> = None;
        let mut line = String::new();
        loop {
            line.clear();
            let n = match stdin_lock.read_line(&mut line) {
                Ok(n) => n,
                Err(_) => return,
            };
