fn send_response(stdout: &Arc<Mutex<std::io::Stdout>>, id: serde_json::Value, result: serde_json::Value) {
    let resp = serde_json::json!({
        "jsonrpc": "2.0",
        "result": result,
        "id": id
    });
    send_raw(stdout, &resp);
}

fn send_error(stdout: &Arc<Mutex<std::io::Stdout>>, id: serde_json::Value, code: i32, message: &str, data: Option<serde_json::Value>) {
    let mut err = serde_json::json!({
        "code": code,
        "message": message
    });
    if let Some(d) = data {
        err["data"] = d;
    }
    let resp = serde_json::json!({
