fn handle_notification(
    method: &str,
    params: Option<serde_json::Value>,
    state: &Arc<Mutex<ServerState>>,
    _stdout: &Arc<Mutex<std::io::Stdout>>,
) -> bool {
    match method {
        "initialized" => {
            // No-op
            return false;
        }
        "exit" => {
            // Already handled earlier (sets exited), but just in case
            let mut s = state.lock().unwrap();
            s.exited = true;
            return false;
        }
        "textDocument/didOpen" => {
            let params_val = match params {
                Some(v) => v,
                None => return false,
            };
            let parsed: Result<DidOpenParams, _> = serde_json::from_value(params_val);
            let didopen = match parsed {
                Ok(p) => p,
                Err(_) => return false,
            };
            // Ensure toolchain? If sysroot missing, try setup? Original didOpen with missing sysroot?
            // We didn't test. Assume same as initialize: ensure, if fails, don't proceed?
            // For now, ensure, if fails, return (no analysis).
            let runtime = {
                let s = state.lock().unwrap();
                s.backend.runtime.clone()
            };
            if toolchain::ensure_toolchain(&runtime).is_err() {
                return false;
            }
            let should_analyze = {
                let s = state.lock().unwrap();
                s.backend.process_didopen(didopen.text_document.uri)
            };
            if should_analyze {
                let s = state.lock().unwrap();
                s.backend.trigger_analysis();
            }
            return false;
        }
        "workspace/didChangeWorkspaceFolders" => {
            let params_val = match params {
                Some(v) => v,
                None => return false,
            };
            let parsed: Result<DidChangeWorkspaceFoldersParams, _> = serde_json::from_value(params_val);
            let change = match parsed {
                Ok(p) => p,
                Err(_) => return false,
            };
            let runtime = {
                let s = state.lock().unwrap();
                s.backend.runtime.clone()
            };
            if toolchain::ensure_toolchain(&runtime).is_err() {
                return false;
            }
            let should_analyze = {
                let s = state.lock().unwrap();
                s.backend.process_workspace_folders_changed(change.event.added)
            };
            if should_analyze {
                let s = state.lock().unwrap();
                s.backend.trigger_analysis();
            }
            return false;
        }
        "textDocument/didChange"
        | "textDocument/didClose"
        | "textDocument/didSave"
        | "textDocument/willSave"
        | "workspace/didChangeConfiguration"
        | "workspace/didChangeWatchedFiles"
        | "workspace/didCreateFiles"
        | "workspace/didDeleteFiles"
        | "workspace/didRenameFiles"
        | "$/cancelRequest"
        | "$/progress"
        | "$/logTrace"
        | "$/setTrace" => {
            // Ignore
            return false;
        }
        _ => return false,
    }
}

fn handle_cursor(req: CursorRequest, _state: &Arc<Mutex<ServerState>>) -> CursorResponse {
    // Determine path: if uri is file:// and path exists and is file, Some(path), else None
    let path_opt = match req.document.uri.to_file_path() {
        Ok(p) => {
            if p.is_file() {
                Some(p.to_string_lossy().to_string())
            } else {
                None
            }
        }
        Err(_) => None,
    };
    CursorResponse {
        decorations: vec![],
        is_analyzed: false,
        path: path_opt,
        status: "error".to_string(),
    }
}

fn format_serde_error(e: &serde_json::Error) -> String {
    // serde_json::Error's Display gives messages like "missing field `position`", "invalid type: ...", etc.
    // But it also includes " at line X column Y"? No, for from_value, it doesn't include line/col, just message.
    // Original messages are exactly from serde (e.g., "missing field `position`").
    // So just use e.to_string().
    e.to_string()
}
