use std::io::{BufRead, Read, Write};
use std::sync::{Arc, Mutex};

use crate::lsp::backend::Backend;
use crate::lsp::protocol::*;
use crate::toolchain;

struct ServerState {
    initialized: bool,
    shutdown: bool,
    exited: bool,
    backend: Backend,
}

pub fn run() {
    let runtime = toolchain::default_runtime_dir();
    // Ensure toolchain? For LSP, does it auto-setup toolchain on startup or on first analysis?
    // Original LSP with missing sysroot: when does it try to install?
    // For check, it tries immediately on startup (before analysis).
    // For LSP, when initialize with file and missing sysroot, does it try to install?
    // Let's see: LSP initialize with file and missing sysroot should try to install (like check).
    // When does that happen? During initialize processing (when it does toolchain check for targets).
    // At that point, if sysroot missing, it should call ensure_toolchain (which logs sysroot not found + install...).
    // But what about LSP startup with no targets (initialize with None)? No toolchain check, no install.
    // So don't ensure at startup, only when processing targets.
    let backend = Backend::new(runtime);
    let state = Arc::new(Mutex::new(ServerState {
        initialized: false,
        shutdown: false,
        exited: false,
        backend,
    }));

    let stdin = std::io::stdin();
    let mut stdin_lock = stdin.lock();
    let stdout = std::io::stdout();
    let stdout_mutex = Arc::new(Mutex::new(stdout));

    loop {
        // Read headers
        let mut content_length: Option<usize> = None;
        let mut line = String::new();
        loop {
            line.clear();
            let n = match stdin_lock.read_line(&mut line) {
                Ok(n) => n,
                Err(_) => return,
            };
            if n == 0 {
                // EOF
                std::process::exit(0);
            }
            let trimmed = line.trim();
            if trimmed.is_empty() {
                break;
            }
            if let Some(colon) = trimmed.find(':') {
                let (key, value) = trimmed.split_at(colon);
                let value = value[1..].trim();
                if key.eq_ignore_ascii_case("Content-Length") {
                    if let Ok(len) = value.parse::<usize>() {
                        content_length = Some(len);
                    }
                }
            }
        }
        let len = match content_length {
            Some(l) => l,
            None => continue,
        };
        let mut body = vec![0u8; len];
        if stdin_lock.read_exact(&mut body).is_err() {
            return;
        }
        let body_str = String::from_utf8_lossy(&body).to_string();
        // Parse JSON
        let value: serde_json::Value = match serde_json::from_str(&body_str) {
            Ok(v) => v,
            Err(_) => {
                // Parse error
                send_error(&stdout_mutex, serde_json::Value::Null, -32700, "Parse error", None);
                continue;
            }
        };
        // Handle message
        let should_exit = handle_message(value, &state, &stdout_mutex);
        if should_exit {
            // Original never exits on exit message alone, only on EOF. So ignore.
            // But if exited flag set, we still continue loop (ignoring further messages) until EOF.
            continue;
        }
        // Check if stdin EOF? Loop will handle.
    }
}

fn send_response(stdout: &Arc<Mutex<std::io::Stdout>>, id: serde_json::Value, result: serde_json::Value) {
    let resp = serde_json::json!({
        "jsonrpc": "2.0",
        "result": result,
        "id": id
    });
    send_raw(stdout, &resp);
}

fn send_error(stdout: &Arc<Mutex<std::io::Stdout>>, id: serde_json::Value, code: i32, message: &str, data: Option<serde_json::Value>) {
    let mut err = serde_json::json!({
        "code": code,
        "message": message
    });
    if let Some(d) = data {
        err["data"] = d;
    }
    let resp = serde_json::json!({
        "jsonrpc": "2.0",
        "error": err,
        "id": id
    });
    send_raw(stdout, &resp);
}

fn send_raw(stdout: &Arc<Mutex<std::io::Stdout>>, value: &serde_json::Value) {
    let body = serde_json::to_string(value).unwrap();
    let header = format!("Content-Length: {}\r\n\r\n", body.len());
    let mut out = stdout.lock().unwrap();
    let _ = out.write_all(header.as_bytes());
    let _ = out.write_all(body.as_bytes());
    let _ = out.flush();
}

fn handle_message(
    value: serde_json::Value,
    state: &Arc<Mutex<ServerState>>,
    stdout: &Arc<Mutex<std::io::Stdout>>,
