    // Check exited first? Even if message is invalid, if exited, ignore (no response).
    {
        let s = state.lock().unwrap();
        if s.exited {
            return false;
        }
    }

    // Value must be object
    let obj = match value.as_object() {
        Some(o) => o,
        None => {
            send_error(stdout, serde_json::Value::Null, -32600, "Invalid request", None);
            return false;
        }
    };

    // Check jsonrpc
    let jsonrpc = obj.get("jsonrpc");
    if jsonrpc != Some(&serde_json::Value::String("2.0".to_string())) {
        send_error(stdout, serde_json::Value::Null, -32600, "Invalid request", None);
        return false;
    }

    // Get id (optional)
    let id_opt = obj.get("id").cloned();
    let is_notification = id_opt.is_none();
    // Validate id if present: must be string|integer|null, else Invalid request with null id
    if let Some(id) = &id_opt {
        let valid = match id {
            serde_json::Value::String(_) => true,
            serde_json::Value::Number(n) => n.is_i64() || n.is_u64(),
            serde_json::Value::Null => true,
            _ => false,
        };
        if !valid {
            send_error(stdout, serde_json::Value::Null, -32600, "Invalid request", None);
            return false;
        }
    }

    // Get method
    // If missing, treat as "" (Method not found with id echoed if request, no response if notification?).
    // For missing method as notification (no id), what? Probably ignore (no response).
    // For missing method as request, return Method not found with data "".
    let method_opt = obj.get("method");
    let method_str: Option<String> = match method_opt {
        None => {
            // Missing method
            if is_notification {
                // Notification with no method? Ignore (no response)
                return false;
            } else {
                // Request with missing method: Method not found with data ""
                let id = id_opt.unwrap();
                // Check initialized/shutdown/exited? For missing method, is it considered unknown (bypass checks) or known?
                // Original: missing method as request after init gave Method not found with data "" (we tested missing method with id 1 after no init? Actually we tested missing method without init? No, we tested missing method as first message (before init) and got Method not found with data "" and id 1.
                // That was before init, and it returned Method not found (not Server not initialized), so missing method bypasses initialize check (like unknown).
                // Good. So for missing method, directly return Method not found, bypassing all checks.
                send_error(stdout, id, -32601, "Method not found", Some(serde_json::Value::String("".to_string())));
                return false;
            }
        }
        Some(serde_json::Value::String(s)) => Some(s.clone()),
        Some(_) => {
            // Method present but not string (number, null, bool, etc.): Invalid request with null id
            // What about id? Original for method=123 with id=1 gave Invalid request with null id (not echoing 1).
            // Good. So return null id, not echoed.
            // Even if notification (no id)? For notification with method non-string, what? Probably Invalid request? But notifications have no id, so no response?
            // Actually for notification with invalid method type, should we respond? Notifications never respond, even on error.
            // But our case here: method non-string as notification (no id) -> should give no response (ignore).
            // As request (with id) -> Invalid request with null id.
            if is_notification {
                return false;
            } else {
                send_error(stdout, serde_json::Value::Null, -32600, "Invalid request", None);
                return false;
            }
        }
    };
    let method = method_str.unwrap();

    // Handle exit specially: any exit message sets exited flag, no response (even as request)
    if method == "exit" {
        let mut s = state.lock().unwrap();
        s.exited = true;
        return false;
    }

    // If exited (already handled above, but double-check after exit handling? No, exit sets exited, future messages ignored.
    // For current message which is exit, we already returned.

    // Get params (optional)
    let params_opt = obj.get("params").cloned();
    let has_params = params_opt.is_some();

