    // Known methods enforce checks.
    let is_known = is_known_method(&method);
    // Special: $/progress, $/logTrace, $/setTrace as requests give NO RESPONSE (not even error), even before init? What about before init?
    // We didn't test $/progress before init. Likely also NO RESPONSE (since it's special, bypass checks? Or check first?).
    // For safety, handle special NO RESPONSE methods first, before initialize/shutdown checks? Or after?
    // Original: $/progress as request after init gave NO RESPONSE. Before init, what? Probably also NO RESPONSE (since it's not a valid request, just ignored).
    // Similarly, exit already handled.
    // Let's handle special first: if method in ["$/progress", "$/logTrace", "$/setTrace"] and is request (has id), return NO RESPONSE (ignore).
    // If notification, also ignore.
    // Should this bypass initialize/shutdown? Yes, just ignore always.
    if method == "$/progress" || method == "$/logTrace" || method == "$/setTrace" {
        return false;
    }

    // Check state
    {
        let s = state.lock().unwrap();
        if !s.initialized {
            // Not initialized
            if method == "initialize" {
                // Handle below (don't return Server not initialized)
            } else {
