                        return false;
                    } else {
                        let id = id_opt.unwrap();
                        send_error(stdout, id, -32601, "Method not found", Some(serde_json::Value::String(method.clone())));
                        return false;
                    }
                } else {
                    // Known: Server not initialized (for requests) or ignore (for notifications)
