use chrono::Utc;
use log::{Level, Metadata, Record};
use std::sync::Once;

static INIT: Once = Once::new();

struct SimpleLogger;

impl log::Log for SimpleLogger {
    fn enabled(&self, _metadata: &Metadata) -> bool {
        true
    }

    fn log(&self, record: &Record) {
        let now = Utc::now();
        let ts = now.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string();
        let level = match record.level() {
            Level::Error => "ERROR",
            Level::Warn => "WARN",
            Level::Info => "INFO",
            Level::Debug => "DEBUG",
            Level::Trace => "TRACE",
        };
        eprintln!("{} {:5} [{}] {}", ts, level, record.target(), record.args());
    }

    fn flush(&self) {}
}

static SIMPLE: SimpleLogger = SimpleLogger;
static mut FILTERED: Option<env_filter::FilteredLog<&'static SimpleLogger>> = None;

fn parse_simple_level(s: &str) -> Option<log::LevelFilter> {
    let trimmed = s.trim();
    if trimmed.contains(',') || trimmed.contains('=') || trimmed.contains('/') {
        return None;
    }
    match trimmed.to_ascii_lowercase().as_str() {
        "off" => Some(log::LevelFilter::Off),
        "error" => Some(log::LevelFilter::Error),
        "warn" => Some(log::LevelFilter::Warn),
        "info" => Some(log::LevelFilter::Info),
        "debug" => Some(log::LevelFilter::Debug),
        "trace" => Some(log::LevelFilter::Trace),
        _ => None,
    }
}

pub fn init(default_level: log::LevelFilter) {
    INIT.call_once(|| {
        let mut builder = env_filter::Builder::new();
        builder.filter_level(default_level);
        if let Ok(s) = std::env::var("RUST_LOG") {
            if !s.is_empty() {
                if let Some(level) = parse_simple_level(&s) {
                    builder.filter_level(level);
                }
            }
        }
        let filter = builder.build();
        let filtered = env_filter::FilteredLog::new(&SIMPLE, filter);
        unsafe {
            FILTERED = Some(filtered);
            let logger = FILTERED.as_ref().unwrap();
            let _ = log::set_logger(logger as &'static dyn log::Log);
        }
        log::set_max_level(log::LevelFilter::Trace);
    });
}
